1	     1	//! Camera layouts' geometry (road map "creator-jobs" CO6, spec §11 CO-60,
2	     2	//! CO-65): where a layout puts the camera and the screen, as the six
3	     3	//! placement keys `switch_layout` writes on each — `x`, `y`, `scale`,
4	     4	//! `crop`, `corner_radius`, `opacity` — and nothing else. Pure: every
5	     5	//! number is read from the container's canvas and the source sizes.
6	     6	//!
7	     7	//! W × H is the container's canvas (a nest's own inside a scope) and
8	     8	//! `m = MARGIN·min(W, H)`. Every scale is clamped to
9	     9	//! `SCALE_MIN…SCALE_MAX`; `x` and `y` are rounded half away from zero to
10	    10	//! whole canvas pixels, as CAM-10 (3) rounds them; scale, crop and radius
11	    11	//! are not. A radius is written in SOURCE pixels, its canvas length ÷ the
12	    12	//! scale. A crop's centre is placed by `edit_zoom.rs`'s (★): the cropped
13	    13	//! centre is the anchor plus `s·((l − r)/2, (t − b)/2)`.
14	    14	//!
15	    15	//! - **Full placement** is `add_clip`'s: 0, 0, `fit_scale`, no crop,
16	    16	//!   radius 0, opacity 1 — the screen's in `corner`, `camera_full` and
17	    17	//!   `screen_only`.
18	    18	//! - **corner**: the box is `CORNER_WIDTH·W × CORNER_HEIGHT·H`, the
19	    19	//!   picture's outer corner `CORNER_INSET` of each axis in from the chosen
20	    20	//!   canvas corner. `square` and `rounded` fit the whole camera in it
21	    21	//!   (CAM-10 (3)'s `cornerPatch` exactly); `rounded`'s radius is
22	    22	//!   `ROUNDED_RADIUS` of the box's shorter side. `circle` crops the largest
23	    23	//!   square of the source, centred on `focus`, to the box's shorter side,
24	    24	//!   with a radius of half the square's side.
25	    25	//! - **side_by_side**: the screen fitted in the left `SCREEN_SHARE` of the
26	    26	//!   inner width `W − 3m` and `H − 2m` tall, centred there; the camera
27	    27	//!   cropped to fill the right third; `PANEL_RADIUS` of the canvas's
28	    28	//!   shorter side on each.
29	    29	//! - **stacked**: the screen at `min((W − 2m)/sw, (H − 3m)·SCREEN_SHARE/sh)`,
30	    30	//!   centred across, its top at m; the camera cropped to fill the
31	    31	//!   `(W − 2m)`-wide rest below it, m between; the same radii.
32	    32	//! - **camera_full**: the camera at `fill_scale`, uncropped, square.
33	    33	//! - **screen_only**: the camera keeps where it is, at opacity 0.
34	    34	//!
35	    35	//! `focus` (CO-65) is a point in the camera's source pixels from the
36	    36	//! UNCROPPED source's centre, y down; a crop is centred on it and clamped
37	    37	//! inside the source.
38	    38	
39	    39	use serde::{Deserialize, Serialize};
40	    40	use serde_json::{json, Value};
41	    41	
42	    42	use crate::model::{Crop, Project, VideoProps};
43	    43	use crate::props_check::{SCALE_MAX, SCALE_MIN};
44	    44	use crate::time::{Ticks, TIMESCALE};
45	    45	
46	    46	/// The corner box's width, as a fraction of the canvas's (CAM-10 (3)).
47	    47	pub(crate) const CORNER_WIDTH: f64 = 0.25;
48	    48	/// The corner box's height, as a fraction of the canvas's.
49	    49	pub(crate) const CORNER_HEIGHT: f64 = 1.0 / 3.0;
50	    50	/// The corner picture's inset from the canvas's edges, per axis: the 90 %
51	    51	/// ring of View ▸ Safe Areas.
52	    52	pub(crate) const CORNER_INSET: f64 = 0.05;
53	    53	/// `rounded`'s radius, as a fraction of the corner box's shorter side.
54	    54	pub(crate) const ROUNDED_RADIUS: f64 = 0.08;
55	    55	/// The margin round and between the panels, of the canvas's shorter side.
56	    56	pub(crate) const MARGIN: f64 = 0.04;
57	    57	/// Each panel's radius in `side_by_side` and `stacked`, of the canvas's
58	    58	/// shorter side.
59	    59	pub(crate) const PANEL_RADIUS: f64 = 0.02;
60	    60	/// The screen's share of the inner width (`side_by_side`) or height
61	    61	/// (`stacked`).
