214	   214	/// A `cw × ch` crop of an `a × b` source centred on `focus` (from the
215	   215	/// uncropped centre, y down), clamped inside the source.
216	   216	fn centred_crop(source: (f64, f64), size: (f64, f64), focus: (f64, f64)) -> Crop {
217	   217	    let (a, b) = source;
218	   218	    let axis = |whole: f64, part: f64, at: f64| {
219	   219	        let part = if part >= whole - 1e-9 { whole } else { part };
220	   220	        let room = (whole - part) / 2.0;
221	   221	        // `switch_layout` refuses a non-finite focus before it gets here.
222	   222	        let centre = at.clamp(-room, room);
223	   223	        (room + centre, room - centre)
224	   224	    };
225	   225	    let (l, r) = axis(a, size.0, focus.0);
226	   226	    let (t, b) = axis(b, size.1, focus.1);
227	   227	    Crop { l, t, r, b }
228	   228	}
229	   229	
230	   230	/// The `x`, `y` that put a cropped picture's centre at `centre` (an offset
231	   231	/// from the canvas centre) at scale `s` — (★) turned round, rounded.
232	   232	fn place(centre: (f64, f64), scale: f64, crop: &Crop) -> (f64, f64) {
233	   233	    let x = centre.0 - scale * (crop.l - crop.r) / 2.0;
234	   234	    let y = centre.1 - scale * (crop.t - crop.b) / 2.0;
235	   235	    (x.round(), y.round())
236	   236	}
237	   237	
238	   238	/// The camera cropped to fill a `bw × bh` box centred at `centre`.
239	   239	fn filled(
240	   240	    source: (f64, f64),
241	   241	    boxed: (f64, f64),
242	   242	    centre: (f64, f64),
243	   243	    focus: (f64, f64),
244	   244	    radius: f64,
245	   245	) -> Placement {
246	   246	    let (a, b) = source;
247	   247	    let scale = clamp_scale((boxed.0 / a).max(boxed.1 / b));
248	   248	    let crop = centred_crop(source, (boxed.0 / scale, boxed.1 / scale), focus);
249	   249	    let (x, y) = place(centre, scale, &crop);
250	   250	    Placement {
251	   251	        x,
252	   252	        y,
253	   253	        scale,
254	   254	        crop,
255	   255	        corner_radius: radius / scale,
256	   256	        opacity: 1.0,
257	   257	    }
258	   258	}
