272	   272	/// The screen's scale in `stacked`.
273	   273	fn stacked_screen_scale(p: &Project, source: (f64, f64)) -> f64 {
274	   274	    let (w, h, m) = canvas(p);
275	   275	    clamp_scale(((w - 2.0 * m) / source.0).min((h - 3.0 * m) * SCREEN_SHARE / source.1))
