278	   278	/// Where the screen goes in `layout` (CO-60).
279	   279	pub(crate) fn screen_placement(p: &Project, layout: CameraLayout, source: (f64, f64)) -> Placement {
280	   280	    let (w, h, m) = canvas(p);
281	   281	    let radius = PANEL_RADIUS * w.min(h);
282	   282	    match layout {
283	   283	        CameraLayout::SideBySide => {
284	   284	            let bw = (w - 3.0 * m) * SCREEN_SHARE;
285	   285	            let bh = h - 2.0 * m;
286	   286	            let scale = clamp_scale((bw / source.0).min(bh / source.1));
287	   287	            let x = (m + bw / 2.0 - w / 2.0).round();
288	   288	            Placement {
289	   289	                x,
290	   290	                y: 0.0,
291	   291	                scale,
292	   292	                crop: Crop::default(),
293	   293	                corner_radius: radius / scale,
294	   294	                opacity: 1.0,
295	   295	            }
296	   296	        }
297	   297	        CameraLayout::Stacked => {
298	   298	            let scale = stacked_screen_scale(p, source);
299	   299	            let y = (m + source.1 * scale / 2.0 - h / 2.0).round();
300	   300	            Placement {
301	   301	                x: 0.0,
302	   302	                y,
303	   303	                scale,
304	   304	                crop: Crop::default(),
305	   305	                corner_radius: radius / scale,
306	   306	                opacity: 1.0,
307	   307	            }
308	   308	        }
309	   309	        CameraLayout::Corner | CameraLayout::CameraFull | CameraLayout::ScreenOnly => {
310	   310	            full_placement(p, source)
311	   311	        }
312	   312	    }
313	   313	}
314	   314	
315	   315	/// Where the camera goes (CO-60): `screen` is the screen's source size
316	   316	/// (`stacked` stands the camera under it), `kept` the camera's own six keys
317	   317	/// now (`screen_only` keeps them at opacity 0).
318	   318	pub(crate) fn camera_placement(
319	   319	    p: &Project,
320	   320	    choice: &LayoutChoice,
321	   321	    source: (f64, f64),
322	   322	    screen: Option<(f64, f64)>,
323	   323	    kept: &Placement,
324	   324	) -> Placement {
325	   325	    let (w, h, m) = canvas(p);
326	   326	    let panel = PANEL_RADIUS * w.min(h);
327	   327	    let (a, b) = source;
328	   328	    match choice.layout {
329	   329	        CameraLayout::Corner => corner(p, choice, source),
330	   330	        CameraLayout::SideBySide => {
331	   331	            let inner = w - 3.0 * m;
332	   332	            let boxed = (inner * (1.0 - SCREEN_SHARE), h - 2.0 * m);
333	   333	            let left = m + inner * SCREEN_SHARE + m;
334	   334	            let centre = (left + boxed.0 / 2.0 - w / 2.0, 0.0);
335	   335	            filled(source, boxed, centre, choice.focus, panel)
336	   336	        }
337	   337	        CameraLayout::Stacked => {
338	   338	            let above = screen.map_or(0.0, |s| s.1 * stacked_screen_scale(p, s));
339	   339	            let boxed = (w - 2.0 * m, h - 3.0 * m - above);
340	   340	            let centre = (0.0, 2.0 * m + above + boxed.1 / 2.0 - h / 2.0);
341	   341	            filled(source, boxed, centre, choice.focus, panel)
342	   342	        }
343	   343	        CameraLayout::CameraFull => Placement {
344	   344	            x: 0.0,
345	   345	            y: 0.0,
346	   346	            scale: p.fill_scale(a, b),
347	   347	            crop: Crop::default(),
348	   348	            corner_radius: 0.0,
349	   349	            opacity: 1.0,
350	   350	        },
351	   351	        CameraLayout::ScreenOnly => Placement {
352	   352	            opacity: 0.0,
353	   353	            ..*kept
354	   354	        },
355	   355	    }
356	   356	}
