358	   358	/// `corner`'s three shapes.
359	   359	fn corner(p: &Project, choice: &LayoutChoice, source: (f64, f64)) -> Placement {
360	   360	    let (w, h, _) = canvas(p);
361	   361	    let (a, b) = source;
362	   362	    let (bw, bh) = (CORNER_WIDTH * w, CORNER_HEIGHT * h);
363	   363	    let (sx, sy) = choice.corner.signs();
364	   364	    let (ix, iy) = (CORNER_INSET * w, CORNER_INSET * h);
365	   365	    match choice.shape {
366	   366	        LayoutShape::Square | LayoutShape::Rounded => {
367	   367	            let scale = clamp_scale((bw / a).min(bh / b));
368	   368	            let x = (sx * (w / 2.0 - ix - a * scale / 2.0)).round();
369	   369	            let y = (sy * (h / 2.0 - iy - b * scale / 2.0)).round();
370	   370	            let corner_radius = match choice.shape {
371	   371	                LayoutShape::Rounded => ROUNDED_RADIUS * bw.min(bh) / scale,
372	   372	                _ => 0.0,
373	   373	            };
374	   374	            Placement {
375	   375	                x,
376	   376	                y,
377	   377	                scale,
378	   378	                crop: Crop::default(),
379	   379	                corner_radius,
380	   380	                opacity: 1.0,
381	   381	            }
382	   382	        }
383	   383	        LayoutShape::Circle => {
384	   384	            let side = a.min(b);
385	   385	            let crop = centred_crop(source, (side, side), choice.focus);
386	   386	            let scale = clamp_scale(bw.min(bh) / side);
387	   387	            let shown = side * scale / 2.0;
388	   388	            let centre = (sx * (w / 2.0 - ix - shown), sy * (h / 2.0 - iy - shown));
389	   389	            let (x, y) = place(centre, scale, &crop);
390	   390	            Placement {
391	   391	                x,
392	   392	                y,
393	   393	                scale,
394	   394	                crop,
395	   395	                corner_radius: side / 2.0,
396	   396	                opacity: 1.0,
397	   397	            }
398	   398	        }
399	   399	    }
400	   400	}
401	     1	//! `switch_layout` — a camera clip and the screen behind it laid out at the
402	     2	//! playhead (road map "creator-jobs" CO6, spec §11 CO-61, CO-62, CO-64).
403	     3	//! One op, so Clip ▸ Camera Layout ▸ is one undo step, "Camera Layout".
404	     4	//! The geometry is `layout.rs`'s; this file is who is laid out, how far,
405	     5	//! and what refuses.
406	     6	//!
407	     7	//! - **The roles** (CO-64): the camera, playing at `at` with a picture; the
408	     8	//!   screen given (on a track behind) or found — the clip playing at `at`
409	     9	//!   on the front-most visible, non-matte track behind the camera's with a
410	    10	//!   drawn picture. No screen refuses `side_by_side` and `stacked`; the
411	    11	//!   other three lay out the camera alone.
412	    12	//! - **The switch** (CO-61): per role, the clip under `at` gets a LAYOUT
413	    13	//!   ACTION (all six placement keys) at clip time `at − start`, 0.5 s and
414	    14	//!   `ease_in_out` unless told, clamped to the clip and to its next later
415	    15	//!   layout action, at least one frame; at its first frame the layout is
416	    16	//!   its base and a one-frame layout action ends there (a cut). A layout
417	    17	//!   action starting at `at` is replaced; one running at `at` is shortened
418	    18	//!   to end there. The REACH (`edit_layout_reach.rs`) gives every later
419	    19	//!   picture clip on the role's track starting before the next layout
420	    20	//!   action, `through` or the track's end the layout as its base.
421	    21	//! - **The refusals** (CO-62), in order: the camera, the screen, a nest
422	    22	//!   clip asked for a radius it cannot draw, a mover — a non-layout action
423	    23	//!   that moves a role clip and ends after `at` (a full-placement screen
424	    24	//!   exempt in the three layouts that leave it full) — then whatever the
425	    25	//!   composed ops say. `nest: true` nests the moving role's clips first and
426	    26	//!   lays out the nest clip, unless one of them is already laid out.
427	    27	//!
428	    28	//! Composed from `remove_action`, `set_action`, `add_action`,
429	    29	//! `set_action_end`, `set_video` and `nest_clips`, each refusal inherited in
430	    30	//! its own words.
