492	    92	    /// Lays out `s.camera` and its screen at `s.at` (this module's doc).
493	    93	    pub fn switch_layout(&self, s: &LayoutSwitch) -> Result<Outcome, String> {
494	    94	        let at = self.snapped(s.at);
495	    95	        if at < 0 {
496	    96	            return Err(format!("at must not be negative, not {}", s.at));
497	    97	        }
498	    98	        let duration = match s.duration {
499	    99	            None => DEFAULT_SWITCH,
500	   100	            Some(given) => {
501	   101	                let snapped = self.snapped(given);
502	   102	                if snapped <= 0 {
503	   103	                    return Err(format!("duration must be positive, not {given}"));
504	   104	                }
505	   105	                snapped
506	   106	            }
507	   107	        };
508	   108	        let through = match s.through {
509	   109	            None => None,
510	   110	            Some(given) => {
511	   111	                let snapped = self.snapped(given);
512	   112	                if snapped <= at {
513	   113	                    return Err(format!("through must be after at ({at}), not {given}"));
514	   114	                }
515	   115	                Some(snapped)
516	   116	            }
517	   117	        };
518	   118	        let focus = match s.focus {
519	   119	            None => (0.0, 0.0),
520	   120	            Some([x, y]) if x.is_finite() && y.is_finite() => (x, y),
521	   121	            Some([x, y]) => {
522	   122	                return Err(format!("focus must be two finite numbers, not [{x}, {y}]"))
523	   123	            }
524	   124	        };
525	   125	        let choice = LayoutChoice {
526	   126	            layout: s.layout,
527	   127	            shape: s.shape.unwrap_or_default(),
528	   128	            corner: s.corner.unwrap_or_default(),
529	   129	            focus,
530	   130	        };
