532	   132	        // The camera (CO-64).
533	   133	        let camera = self.require_clip(s.camera)?;
534	   134	        if let Some(why) = self.role_refusal(camera, at) {
535	   135	            return Ok(Outcome::Refused(why));
536	   136	        }
537	   137	        // The screen, given or found.
538	   138	        let screen = match s.screen {
539	   139	            Some(id) => {
540	   140	                let screen = self.require_clip(id)?;
541	   141	                if let Some(why) = self.role_refusal(screen, at) {
542	   142	                    return Ok(Outcome::Refused(why));
543	   143	                }
544	   144	                let behind = match (
545	   145	                    self.track_index(screen.track),
546	   146	                    self.track_index(camera.track),
547	   147	                ) {
548	   148	                    (Some(back), Some(front)) => back < front,
549	   149	                    _ => false,
550	   150	                };
551	   151	                if !behind {
552	   152	                    return Ok(Outcome::Refused(format!(
553	   153	                        "the screen (clip {}) must be on a track behind the camera's (clip {})",
554	   154	                        screen.id, camera.id
555	   155	                    )));
556	   156	                }
557	   157	                Some(screen)
558	   158	            }
559	   159	            None => self.screen_behind(camera, at),
560	   160	        };
561	   161	        if screen.is_none() && matches!(s.layout, CameraLayout::SideBySide | CameraLayout::Stacked)
562	   162	        {
563	   163	            return Ok(Outcome::Refused(format!(
564	   164	                "no clip draws behind clip {} at {} to be the screen",
565	   165	                camera.id,
566	   166	                self.layout_timecode(at)
567	   167	            )));
568	   168	        }
