570	   170	        let mut roles = vec![self.role(RoleKind::Camera, camera, at, through)];
571	   171	        if let Some(screen) = screen {
572	   172	            roles.push(self.role(RoleKind::Screen, screen, at, through));
573	   173	        }
574	   174	        let movers: Vec<Option<String>> = roles
575	   175	            .iter()
576	   176	            .map(|role| self.mover_refusal(role, s.layout))
577	   177	            .collect();
