582	   182	            let camera_role = &roles[0];
583	   183	            let becomes = nesting && movers[0].is_some();
584	   184	            let nested = camera_role
585	   185	                .clips()
586	   186	                .find(|c| matches!(c.source, Source::Nest { .. }))
587	   187	                .map(|c| c.id)
588	   188	                .or(becomes.then_some(camera_role.clip.id));
