609	   209	    /// The switch composed once its refusals have passed (CO-61): every
610	   210	    /// placement solved on the project as it is, then per role the layout
611	   211	    /// action at `at` (replacing one starting there, shortening one running
612	   212	    /// there, a cut at a first frame) and the bases of `later`. Shared by
613	   213	    /// `switch_layout` and `reframe_layout.rs`'s replay (spec §11 VR-53 (b)).
614	   214	    pub(crate) fn compose_switch(
615	   215	        &self,
616	   216	        choice: &LayoutChoice,
617	   217	        roles: &[Role<'_>],
618	   218	        at: Ticks,
619	   219	        duration: Ticks,
620	   220	        curve: Curve,
621	   221	    ) -> Result<Outcome, String> {
622	   222	        // Every placement is solved on the project as it is.
623	   223	        let screen_size = roles
624	   224	            .iter()
625	   225	            .find(|role| role.kind == RoleKind::Screen)
626	   226	            .and_then(|role| self.source_size(role.clip));
627	   227	        let mut writes: Vec<RoleWrites> = Vec::new();
628	   228	        for role in roles {
629	   229	            let solve = |clip: &Clip, kept: Placement| -> Option<Placement> {
630	   230	                let source = self.source_size(clip)?;
631	   231	                Some(match role.kind {
632	   232	                    RoleKind::Camera => camera_placement(self, choice, source, screen_size, &kept),
633	   233	                    RoleKind::Screen => screen_placement(self, choice.layout, source),
634	   234	                })
635	   235	            };
636	   236	            let t = at - role.clip.start;
637	   237	            let kept = Placement::of(&self.evaluate_clip(role.clip, t).video);
638	   238	            let Some(end) = solve(role.clip, kept) else {
639	   239	                continue;
640	   240	            };
641	   241	            let bases = role
642	   242	                .later
643	   243	                .iter()
644	   244	                .filter_map(|c| {
645	   245	                    let base = Placement::of(c.video.as_ref()?);
646	   246	                    solve(c, base).map(|p| (c.id, p))
647	   247	                })
648	   248	                .collect();
649	   249	            writes.push((role.clip.id, t, end, bases));
650	   250	        }
651	   251	
652	   252	        let frame = self.frame();
653	   253	        let mut next = self.clone();
654	   254	        for (id, t, end, bases) in &writes {
655	   255	            let (id, t) = (*id, *t);
656	   256	            let clip = self.require_clip(id)?.clone();
657	   257	            let video = end.to_json();
658	   258	            let patch = json!({ "video": video });
659	   259	            // One starting at `at` is replaced; one running at `at` ends there.
660	   260	            if let Some(found) = clip.actions.iter().find(|a| is_layout(a) && a.start == t) {
661	   261	                step!(next, next.remove_action(id, found.id));
662	   262	            }
663	   263	            if let Some(found) = clip
664	   264	                .actions
665	   265	                .iter()
666	   266	                .find(|a| is_layout(a) && a.start < t && t < a.start.saturating_add(a.duration))
667	   267	            {
668	   268	                step!(
669	   269	                    next,
670	   270	                    next.set_action(id, found.id, None, Some(t - found.start), None)
671	   271	                );
672	   272	            }
673	   273	            if t == 0 {
674	   274	                // A cut: the base, and a one-frame action ending at it.
675	   275	                step!(next, next.set_video(&[id], &video));
676	   276	                let action = next.next_id;
677	   277	                step!(next, next.add_action(id, 0, Some(frame)));
678	   278	                step!(next, next.set_action_end(id, action, &patch, &[], None));
679	   279	            } else {
680	   280	                let mut length = duration.min(clip.duration - t);
681	   281	                if let Some(later) = clip
682	   282	                    .actions
683	   283	                    .iter()
684	   284	                    .filter(|a| is_layout(a) && a.start > t)
685	   285	                    .map(|a| a.start)
686	   286	                    .min()
687	   287	                {
688	   288	                    length = length.min(later - t);
689	   289	                }
690	   290	                let length = length.max(frame);
691	   291	                let action = next.next_id;
692	   292	                step!(next, next.add_action(id, t, Some(length)));
693	   293	                step!(next, next.set_action(id, action, None, None, Some(curve)));
694	   294	                step!(next, next.set_action_end(id, action, &patch, &[], None));
695	   295	            }
696	   296	            for (later, base) in bases {
697	   297	                step!(next, next.set_video(&[*later], &base.to_json()));
698	   298	            }
699	   299	        }
700	   300	        self.finish(next)
701	   301	    }
