706	   306	        if !self.has_layout_picture(clip) {
707	   307	            return Some(format!("clip {} has no picture to lay out", clip.id));
708	   308	        }
709	   309	        if !(clip.start <= at && at < clip_end(clip)) {
710	   310	            return Some(format!(
711	   311	                "clip {} does not play at {}",
712	   312	                clip.id,
