719	   319	    /// The screen found behind `camera` at `at` (CO-64): the clip playing
720	   320	    /// there on the front-most track behind the camera's that is shown and
721	   321	    /// not a matte track, drawing a picture, not an adjustment clip.
722	   322	    fn screen_behind(&self, camera: &Clip, at: Ticks) -> Option<&Clip> {
723	   323	        let front = self.track_index(camera.track)?;
724	   324	        self.tracks
725	   325	            .get(..front)?
726	   326	            .iter()
727	   327	            .rev()
728	   328	            .filter(|track| !track.hidden && track.matte.is_none())
729	   329	            .find_map(|track| {
730	   330	                self.clips.iter().find(|c| {
731	   331	                    c.track == track.id
732	   332	                        && c.start <= at
733	   333	                        && at < clip_end(c)
734	   334	                        && c.enabled.video
735	   335	                        && !is_adjustment(c)
736	   336	                        && self.has_layout_picture(c)
737	   337	                })
738	   338	            })
739	   339	    }
