741	   341	    /// `nest: true` (CO-62): each moving role's clips nested, refused when
742	   342	    /// one is already laid out, then the switch on the nest clips.
743	   343	    fn nest_then_switch(
744	   344	        &self,
745	   345	        s: &LayoutSwitch,
746	   346	        roles: &[Role<'_>],
747	   347	        movers: &[Option<String>],
748	   348	    ) -> Result<Outcome, String> {
749	   349	        let mut again = s.clone();
750	   350	        again.nest = None;
751	   351	        let mut next = self.clone();
752	   352	        for (role, mover) in roles.iter().zip(movers) {
753	   353	            if mover.is_none() {
754	   354	                continue;
755	   355	            }
756	   356	            let nested: Vec<&Clip> = role.nested().collect();
757	   357	            if let Some(id) = nested.iter().find(|c| self.laid_out(c)).map(|c| c.id) {
758	   358	                return Ok(Outcome::Refused(format!(
759	   359	                    "clip {id} is already laid out; a nest would lay it out twice."
760	   360	                )));
761	   361	            }
762	   362	            let ids: Vec<u32> = nested.iter().map(|c| c.id).collect();
763	   363	            let before: HashSet<u32> = next.clips.iter().map(|c| c.id).collect();
764	   364	            step!(next, next.nest_clips(&ids, None));
765	   365	            let made = next
766	   366	                .clips
767	   367	                .iter()
768	   368	                .find(|c| !before.contains(&c.id) && matches!(c.source, Source::Nest { .. }))
769	   369	                .map(|c| c.id);
770	   370	            if let Some(made) = made {
771	   371	                match role.kind {
772	   372	                    RoleKind::Camera => again.camera = made,
773	   373	                    RoleKind::Screen => again.screen = Some(made),
774	   374	                }
775	   375	            }
776	   376	        }
777	   377	        match next.switch_layout(&again)? {
778	   378	            Outcome::Applied(laid) => self.finish(laid),
779	   379	            Outcome::Identity => self.finish(next),
780	   380	            Outcome::Refused(why) => Ok(Outcome::Refused(why)),
781	   381	        }
782	   382	    }
783	   383	}
