816	    33	/// One role's clips in the reach.
817	    34	#[derive(Debug, Clone)]
818	    35	pub(crate) struct Role<'a> {
819	    36	    pub kind: RoleKind,
820	    37	    /// The clip playing at `at`.
821	    38	    pub clip: &'a Clip,
822	    39	    /// `at` in project time.
823	    40	    pub at: Ticks,
824	    41	    /// The later picture clips starting inside the reach, in time order.
825	    42	    pub later: Vec<&'a Clip>,
