849	    66	impl Project {
850	    67	    /// The role `kind` played by `clip` (which plays at `at`), its reach
851	    68	    /// found on `clip`'s track (CO-61).
852	    69	    pub(crate) fn role<'a>(
853	    70	        &'a self,
854	    71	        kind: RoleKind,
855	    72	        clip: &'a Clip,
856	    73	        at: Ticks,
857	    74	        through: Option<Ticks>,
858	    75	    ) -> Role<'a> {
859	    76	        let on_track = || self.clips.iter().filter(move |c| c.track == clip.track);
860	    77	        let mut end = on_track().map(clip_end).max().unwrap_or(at);
861	    78	        let mut ender = None;
862	    79	        for owner in on_track() {
863	    80	            for action in owner.actions.iter().filter(|a| is_layout(a)) {
864	    81	                let starts = owner.start.saturating_add(action.start);
865	    82	                if starts > at && starts < end {
866	    83	                    end = starts;
867	    84	                    ender = Some(owner.id);
868	    85	                }
869	    86	            }
870	    87	        }
871	    88	        if let Some(through) = through {
872	    89	            if through < end {
873	    90	                end = through;
874	    91	                ender = None;
875	    92	            }
876	    93	        }
