891	   108	    /// The first mover in `role`'s reach, as CO-62's sentence, or `None`.
892	   109	    /// A screen that already holds its full placement is not checked in a
893	   110	    /// layout that leaves it there.
894	   111	    pub(crate) fn mover_refusal(&self, role: &Role<'_>, layout: CameraLayout) -> Option<String> {
895	   112	        let exempt = |clip: &Clip, placed: Placement| {
896	   113	            role.kind == RoleKind::Screen
897	   114	                && layout.screen_full()
898	   115	                && self
899	   116	                    .source_size(clip)
900	   117	                    .is_some_and(|size| holds_full(&placed, &full_placement(self, size)))
901	   118	        };
902	   119	        for clip in role.clips() {
903	   120	            let under = clip.id == role.clip.id;
904	   121	            let t = role.at - clip.start;
905	   122	            let placed = if under {
906	   123	                Placement::of(&self.evaluate_clip(clip, t).video)
907	   124	            } else {
908	   125	                Placement::of(&clip.video.clone().unwrap_or_default())
909	   126	            };
910	   127	            if exempt(clip, placed) {
911	   128	                continue;
912	   129	            }
913	   130	            let found = clip
914	   131	                .actions
915	   132	                .iter()
916	   133	                .filter(|a| moves(a) && !is_layout(a))
917	   134	                .filter(|a| !under || a.start.saturating_add(a.duration) > t)
918	   135	                .min_by_key(|a| (a.start, a.id));
919	   136	            if let Some(action) = found {
920	   137	                let role_word = role.kind.word();
921	   138	                let (verb, noun) = if is_zoom(action) {
922	   139	                    ("zooms", "zoom")
923	   140	                } else {
924	   141	                    ("moves", "action")
925	   142	                };
926	   143	                return Some(format!(
927	   144	                    "The {role_word} clip {} at {} {verb} (action {}); nest the {role_word}'s \
928	   145	                     clips so the layout moves the nest and the {noun} stays inside it.",
929	   146	                    clip.id,
930	   147	                    self.layout_timecode(clip.start),
931	   148	                    action.id
932	   149	                ));
933	   150	            }
934	   151	        }
935	   152	        None
936	   153	    }
