     1	//! Actions classed by content, with no tag (spec §11 CU-73, CO-63; CJ-8
     2	//! (i)): what an action's end patch DOES, read from its keys. Auto Zoom's
     3	//! Replace removes only zooms (`cursor_zoom.rs`); CO6's `switch_layout`
     4	//! (`edit_layout.rs`, `edit_layout_reach.rs`) reads `is_layout` and `moves`.
     5	//!
     6	//! - A **zoom** is an end whose `video` keys are exactly `scale`, `x` and
     7	//!   `y`, naming no other group (an empty `audio` or `text`, or a `graphic`
     8	//!   with no props, names nothing) and no `speed` — the twin of the app's
     9	//!   `ActionBands.isZoom`, which draws the zoom glyph.
    10	//! - A **layout** names all six [`PLACEMENT_KEYS`] in `video`.
    11	//! - An action **moves** its clip when its `video` names any of the six.
    12	
    13	use serde_json::Value;
    14	
    15	use crate::model::Action;
    16	
    17	/// The keys that place a picture on the canvas.
    18	pub(crate) const PLACEMENT_KEYS: [&str; 6] =
    19	    ["x", "y", "scale", "crop", "corner_radius", "opacity"];
    20	
    21	/// The end's `video` object, when it is one.
    22	fn video(action: &Action) -> Option<&serde_json::Map<String, Value>> {
    23	    action.end.get("video").and_then(Value::as_object)
    24	}
    25	
    26	/// Absent, null or `{}`.
    27	fn names_nothing(group: Option<&Value>) -> bool {
    28	    match group {
    29	        None | Some(Value::Null) => true,
    30	        Some(Value::Object(map)) => map.is_empty(),
    31	        Some(_) => false,
    32	    }
    33	}
    34	
    35	/// A screencast zoom's end: `video` exactly {scale, x, y}; `audio` and
    36	/// `text` naming nothing; `graphic` naming no props; no numeric `speed`.
    37	pub(crate) fn is_zoom(action: &Action) -> bool {
    38	    let Some(video) = video(action) else {
    39	        return false;
    40	    };
    41	    let end = &action.end;
    42	    let graphic_quiet = match end.get("graphic") {
    43	        None | Some(Value::Null) => true,
