    /// The documents' wants, in order: every `ensureMasks()` builds and wants here.
    static let queue = DispatchQueue(label: "com.kgalligan.framejob.cutout-wants", qos: .utility)

    // MARK: - Windows (CO-22 (a))

    /// Every plan video segment (duration > 0) of a clip whose BASE `video.cutout` is set, clipped
    /// to `range` (nil: the whole segment), as a forward window — mirrored about the clip's pivot
    /// when it plays reversed. A segment `range` misses gives none.
    static func windows(
        plan: CompositionPlan, snapshot: ProjectSnapshot, range: Range<Ticks>?
    ) -> [CutoutWindow] {
        var cutOut = Set<UInt32>()
        for clip in snapshot.clips + snapshot.nests.flatMap(\.clips) where clip.video?.cutout != nil {
            cutOut.insert(clip.id)
        }
        guard !cutOut.isEmpty else { return [] }
        let pivots = CutoutPlan(plan: plan, snapshot: snapshot).pivots
        var out: [CutoutWindow] = []
        for track in plan.videoTracks {
            for segment in track.segments where segment.duration > 0 && cutOut.contains(segment.clip) {
                var a = segment.start
                var b = segment.start + segment.duration
                if let range {
                    a = max(a, range.lowerBound)
                    b = min(b, range.upperBound)
                }
                guard a < b else { continue }
                let window = window(segment, from: a, to: b, pivot: pivots[segment.clip])
                if !out.contains(window) { out.append(window) }
            }
        }
        return out
    }

    /// Every plan video segment (duration > 0) of `clip`, whatever its cutout, as a forward
    /// window — mirrored about the clip's pivot when it plays reversed. The camera's crop on the
    /// person reads these (road map creator-jobs CO7, spec §11 CO-70).
    static func windows(of clip: UInt32, plan: CompositionPlan, snapshot: ProjectSnapshot)
        -> [CutoutWindow]
    {
        let pivot = (snapshot.clips + snapshot.nests.flatMap(\.clips)).first { $0.id == clip }
            .flatMap { ReverseMirror.pivot(for: $0, in: snapshot) }
        var out: [CutoutWindow] = []
        for track in plan.videoTracks {
            for segment in track.segments where segment.duration > 0 && segment.clip == clip {
                let window = window(
                    segment, from: segment.start, to: segment.start + segment.duration,
                    pivot: pivot)
                if !out.contains(window) { out.append(window) }
            }
        }
        return out
    }

    /// The analysis kind of `clip`'s masks (CO-106): `foreground` exactly when it is an image
    /// clip whose BASE cutout's subject is `foreground`; else `masks`.
    static func kind(of clip: ClipSnapshot) -> AnalysisKind {
        guard case .image = clip.source, clip.video?.cutout?.subject == .foreground else {
            return .masks
        }
        return .foreground
    }

    /// One window `[0, 1)` of its image per cut picture — an image clip, top-level or nested,
    /// whose BASE `video.cutout` is set — of the kind `kind(of:)` answers (CO-106). A top-level
    /// clip is taken when `[start, start + duration)` meets `range` (nil: always); a nested one
    /// always.
    static func imageWindows(snapshot: ProjectSnapshot, range: Range<Ticks>?) -> [CutoutWindow] {
        func taken(_ clip: ClipSnapshot) -> Bool {
            guard let range else { return true }
            return clip.start < range.upperBound && range.lowerBound < clip.start + clip.duration
        }
        let clips = snapshot.clips.filter(taken) + snapshot.nests.flatMap(\.clips)
        var out: [CutoutWindow] = []
        for clip in clips where clip.video?.cutout != nil {
            guard case .image(let media) = clip.source else { continue }
            let window = CutoutWindow(
                clip: clip.id, media: media, lower: 0, upper: 1, kind: kind(of: clip))
            if !out.contains(window) { out.append(window) }
        }
        return out
    }

    /// The windows a frame at `t` draws cut out: the recipe layers with `background` remove, a
    /// media mask and a composition-track source, each through the segment covering `t` (of the
    /// mask's media), over `[t, t + 1)`; and the layers with an image mask of their own picture,
    /// each as `[0, 1)` of the kind its subject asks (CO-106).
    static func frameWindows(project: ReelProject, at t: Ticks, options: RecipeOptions)
        -> [CutoutWindow]
    {
        let layers = project.recipe(at: t, options: options)?.layers ?? []
        var out: [CutoutWindow] = []
        var i = 0, j = 0
        while i < a.count, j < b.count {
            let low = max(a[i].lowerBound, b[j].lowerBound)
            let high = min(a[i].upperBound, b[j].upperBound)
            if low <= high { out.append(low...high) }
            if a[i].upperBound < b[j].upperBound { i += 1 } else { j += 1 }
        }
        return out
    }

    // MARK: - The centroid (CO-31 (c))

    /// The mean, over `pack`'s frames whose grid index lies in `need` and `coverage` and whose
    /// mask is `found`, of each frame's value-weighted centroid in mask texels (`Σ v·(x + 0.5) /
    /// Σ v`, likewise y), scaled to the media's upright pixels; nil when no frame counts. Any
    /// thread.
    static func centroid(
        pack: MaskPack, need: [ClosedRange<Int>], coverage: [ClosedRange<Int>],
        mediaWidth: Int, mediaHeight: Int
    ) throws -> CGPoint? {
        guard pack.width > 0, pack.height > 0 else { return nil }
        let need = AnalysisStore.merged(need), coverage = AnalysisStore.merged(coverage)
        var perSlot: [Int: (x: Double, y: Double)?] = [:]
        var sumX = 0.0, sumY = 0.0, frames = 0
        for frame in pack.frames {
            let index = Int(frame.index), slot = Int(frame.slot)
            guard need.contains(where: { $0.contains(index) }),
                coverage.contains(where: { $0.contains(index) }), pack.masks[slot].found
            else { continue }
            let point: (x: Double, y: Double)?
            if let known = perSlot[slot] {
                point = known
            } else {
                point = weighted(try pack.mask(slot: slot), width: pack.width, height: pack.height)
                perSlot[slot] = point
            }
            guard let point else { continue }
            sumX += point.x
            sumY += point.y
            frames += 1
        }
        guard frames > 0 else { return nil }
        return CGPoint(
            x: sumX / Double(frames) * Double(mediaWidth) / Double(pack.width),
            y: sumY / Double(frames) * Double(mediaHeight) / Double(pack.height))
    }

    /// One mask's value-weighted centroid in texels; nil for an empty mask.
    private static func weighted(_ mask: [UInt8], width: Int, height: Int)
        -> (x: Double, y: Double)?
    {
        var total = 0.0, x = 0.0, y = 0.0
        for row in 0..<height {
            var rowSum = 0.0
            for column in 0..<width {
                let v = Double(mask[row * width + column])
                rowSum += v
                x += v * (Double(column) + 0.5)
            }
            total += rowSum
            y += rowSum * (Double(row) + 0.5)
        }
        guard total > 0 else { return nil }
        return (x / total, y / total)
    }

    // MARK: - The stamp, once per cache folder, media and URL (main only)

    private struct StampKey: Hashable {
        let folder: String
        let kind: AnalysisKind
        let media: UInt32
        let url: URL
    }

    private struct StampEntry {
        let media: MediaSnapshot
        let lut: URL?
        let stamp: AnalysisStamp?
    }

    private static var stamps: [StampKey: StampEntry] = [:]

    /// The stamp of `kind` `ProjectDocument.analysisRequest` would make for `media` at `url`:
    /// its asset read only when the media, its URL or its LUT's URL changed. Main thread.
    static func stamp(
        media: MediaSnapshot, url: URL, cacheDir: URL, in document: ProjectDocument,
        kind: AnalysisKind = .masks
    ) -> AnalysisStamp? {
        let lutID = media.color?.lut
        let lut = lutID.flatMap { document.project.snapshot.media($0) }.flatMap(mediaURL(for:))
        let key = StampKey(
            folder: cacheDir.standardizedFileURL.path, kind: kind, media: media.id, url: url)
        if let entry = stamps[key], entry.media == media, entry.lut == lut { return entry.stamp }
        var urls = [media.id: url]
        if let lutID, let lut { urls[lutID] = lut }
        let (input, fullRange) = ProjectDocument.analysisInput(media: media, url: url, urls: urls)
        let stamp = AnalysisStamp.make(
            kind: kind, media: media, url: url, input: input, fullRange: fullRange)
        stamps[key] = StampEntry(media: media, lut: lut, stamp: stamp)
        return stamp
    }
