        let cw = Double(canvasWidth)
        let ch = Double(canvasHeight)
        let sw = Double(sourceWidth)
        let sh = Double(sourceHeight)
        let fit = min(cornerWidthFraction * cw / sw, cornerHeightFraction * ch / sh)
